/** Checks the generated samples and runs every happy-path flow through the real machines (your stubs). */
class TradingGenGeneratedTest {

    private static final Path SAMPLES = Path.of(System.getProperty("ecosystem.samples", "samples"));

    @Test
    void samplesBindToTheirPayloadClassesAndValidate() throws IOException {
        int checked = 0;
        for (var machine : TradingGenMachines.ALL.values()) {
            for (StateMachineSpec.Edge e : machine.spec().edges()) {
                Path sample = SAMPLES.resolve(machine.smType()).resolve(e.eventType() + ".json");
                if (e.payloadType() == null || !Files.exists(sample)) {
                    continue;
                }
                Object bound = ModelJson.read(Files.readString(sample), e.payloadType());
                if (bound instanceof ModelObject mo) {
                    assertEquals(List.of(), mo.validationErrors(), sample.toString());
                }
                checked++;
            }
        }
        assertTrue(checked > 0, "no samples under " + SAMPLES.toAbsolutePath());
    }

    /** Every flow under samples/flows, applied as the worker applies events (load, decide, one transaction). */
    @Test
    void happyPathFlowsReachTerminalStates() throws IOException {
        MachineHarness harness = new MachineHarness();
        TradingGenMachines.ALL.forEach((type, machine) -> harness.register(type, machine.impl()));
        List<Path> flows;
        try (Stream<Path> s = Files.list(SAMPLES.resolve("flows"))) {
            flows = s.filter(p -> p.toString().endsWith(".json")).sorted().toList();
        }
        assertTrue(!flows.isEmpty(), "no flows");
        int n = 0;
        for (Path flow : flows) {
            String last = null;
            String smType = null;
            JsonNode doc = Json.MAPPER.readTree(Files.readString(flow));
            for (JsonNode e : doc.path("events")) {
                JsonNode p = e.get("payload");
                EventEnvelope sample = TradingGenEvents.envelope(e.path("smType").asText(), e.path("eventType").asText(),
                        e.path("instanceKey").asText(), p == null || p.isNull() ? null : Json.write(p));
                EventEnvelope event = new EventEnvelope(flow.getFileName() + "-" + n++, sample.smType(), sample.instanceKey(),
                        sample.eventType(), sample.lockKeys(), sample.payload(), 0, 0);
                TransitionResult r = harness.apply(event);
                assertTrue(r.accepted(), flow.getFileName() + " " + event.eventType() + " rejected: " + r);
                last = r.toState();
                smType = event.smType();
            }
            // a chained machine's flow stops where the chain (concert::sm.emits) takes over
            boolean chained = doc.path("description").asText().contains("(then chained");
            assertTrue(last != null && (chained || TradingGenMachines.get(smType).spec().isTerminal(last)),
                    flow.getFileName() + " ends in non-terminal state " + last);
        }
    }
}
